package com.ruoyi.ai.service;import java.util.*;import org.springframework.stereotype.Service;import com.ruoyi.ai.domain.AiPageConfig;import com.ruoyi.ai.mapper.AiPageConfigMapper;import com.ruoyi.common.exception.ServiceException;import com.ruoyi.common.utils.SecurityUtils;import com.ruoyi.common.utils.StringUtils;@Service public class AiPageConfigService{private final AiPageConfigMapper mapper;public AiPageConfigService(AiPageConfigMapper m){mapper=m;}public List<AiPageConfig> list(){return mapper.selectAll();}public boolean isEnabled(String route){if(StringUtils.isBlank(route))return false;AiPageConfig p=mapper.selectByRoute(route);if(p==null){String n=route.replaceAll("/\\d+(?=/|$)","/*");if(!n.equals(route))p=mapper.selectByRoute(n);}return p!=null&&"0".equals(p.getEnabled());}public void setEnabled(Long id,boolean e){if(mapper.updateEnabled(id,e?"0":"1",SecurityUtils.getUsername())!=1)throw new ServiceException("页面能力配置不存在");}}
